mapper.select:
SELECT 
  FROM org02_info a, org01_code b
 WHERE a.org02_code_id = #{codeId}
   AND b.org01_code_id = a.org02_code_id
   AND b.org01_company_id = #{companyId}
 ORDER BY a.org02_mod_date DESC

